1	// Deno Deploy / Supabase Edge Function for Resend webhook
2	import { createClient } from 'https://esm.sh/@supabase/supabase-js@2';
3	import { Webhook } from 'https://esm.sh/svix@1.15.0';
4	import { ocrFromUrl, processEmailText, textToImage, type OcrResult } from '../_shared/mistral.ts';
5	import {
6		resolveEmailReceiptDate,
7		type EmailReceiptDateResult
8	} from '../_shared/emailReceiptDate.ts';
9	import { fetchExchangeRate } from '../_shared/exchangeRate.ts';
10	import {
11		isSupportedReceiptType,
12		isInlineAttachment,
13		hasUsableOcrData,
14		hasSupportedAttachments
15	} from '../_shared/attachmentFiltering.ts';
16	import {
17		sendNotificationEmail as sendResendNotification,
18		type NotificationType
19	} from '../_shared/notify.ts';
20	import { parseSenderEmail } from '../_shared/emailParsing.ts';
21	import { errText } from '../_shared/errText.ts';
22	
23	interface ResendAttachmentMetadata {
24		id: string;
25		filename: string;
26		content_type: string;
27		content_disposition?: string;
28		content_id?: string;
29	}
30	
31	interface ResendWebhookEvent {
32		type: string;
33		created_at: string;
34		data: {
35			email_id: string;
36			from: string;
37			to: string[];
38			subject: string;
39			created_at: string;
40			message_id: string;
41			bcc: string[];
42			cc: string[];
43			attachments: ResendAttachmentMetadata[];
44		};
45	}
46	
47	interface ResendEmail {
48		email_id: string;
49		from: string;
50		to: string[];
51		subject: string;
52		html: string | null;
53		text: string | null;
54		headers: Record<string, string>;
55	}
56	
57	interface ResendAttachment {
58		filename: string;
59		content_type: string;
60		size: number;
61		download_url: string;
62		expires_at: string;
63		// Present on the download-URL response; used to skip inline attachments.
64		content_id?: string;
65		content_disposition?: string;
66	}
67	
68	/** Service-role client used to bypass RLS for webhook-driven inserts. */
69	function createServiceClient(url: string, key: string) {
70		return createClient(url, key, {
71			auth: { autoRefreshToken: false, persistSession: false }
72		});
73	}
74	
75	/** The Supabase client this function threads through its helpers. */
76	type SupabaseClient = ReturnType<typeof createServiceClient>;
77	
78	/** The receipt row insert helpers return (only these fields are read). */
79	interface InsertedReceipt {
80		id?: string;
81		merchant_name?: string | null;
82		total_amount?: number | null;
83		[key: string]: unknown;
84	}
85	
86	function jsonResponse(status: number, body: unknown): Response {
87		return new Response(JSON.stringify(body), {
88			status,
89			headers: { 'Content-Type': 'application/json' }
90		});
91	}
92	
93	/**
94	 * Verifies the Resend webhook signature using Svix library
95	 * Based on: https://resend.com/docs/dashboard/webhooks/verify-webhooks-requests
96	 */
97	function verifyWebhookSignature(headers: Headers, payload: string, signingSecret: string): boolean {
98		const svixId = headers.get('svix-id');
99		const svixTimestamp = headers.get('svix-timestamp');
100		const svixSignature = headers.get('svix-signature');
101	
102		console.log('Signature verification headers:', {
103			hasSignature: !!svixSignature,
104			hasTimestamp: !!svixTimestamp,
105			hasId: !!svixId
106		});
107	
108		if (!svixId || !svixTimestamp || !svixSignature) {
109			console.error('Missing webhook signature headers:', {
110				signature: svixSignature ? 'present' : 'missing',
111				timestamp: svixTimestamp ? 'present' : 'missing',
112				id: svixId ? 'present' : 'missing'
113			});
114			return false;
115		}
116	
117		try {
118			const wh = new Webhook(signingSecret);
119	
120			// Verify the webhook - this will throw on error
121			wh.verify(payload, {
122				'svix-id': svixId,
123				'svix-timestamp': svixTimestamp,
124				'svix-signature': svixSignature
125			});
126	
127			console.log('Webhook signature verified successfully');
128			return true;
129		} catch (err) {
130			console.error('Webhook signature verification failed:', err);
131			return false;
132		}
133	}
134	
135	async function uploadToStorage(
136		supabase: SupabaseClient,
137		userId: string,
138		bytes: Uint8Array,
139		contentType: string,
140		ext: string
141	): Promise<{ path: string; signedUrl: string }> {
142		const path = `${userId}/${crypto.randomUUID()}.${ext}`;
143		const { error } = await supabase.storage
144			.from('receipts')
145			.upload(path, bytes, { contentType, upsert: false });
146		if (error) throw error;
147		// #{#sec1b} Use signed URL — receipts bucket is private (#{#sec1a})
148		// 5-minute expiry matches OCR signed URL pattern in ReceiptService.ts
149		const { data, error: signError } = await supabase.storage
150			.from('receipts')
151			.createSignedUrl(path, 300);
152		if (signError) throw signError;
153		return { path, signedUrl: data.signedUrl };
154	}
155	
156	// #{#fcr1a} #{#fcr2a} Best-effort exchange rate lookup for foreign currency receipts.
157	// Returns null if currency is CAD/unknown, date is missing, or the API call fails —
158	// matches ReceiptService.uploadAndCreate so the receipt still saves without a rate.
159	async function fetchRateForReceipt(
160		currency: string | null | undefined,
161		transactionDate: string | null | undefined
162	): Promise<number | null> {
163		if (!currency || currency === 'CAD' || !transactionDate) return null;
164		try {
165			return await fetchExchangeRate(currency, transactionDate);
166		} catch (err) {
167			console.error('Exchange rate fetch failed:', err);
168			return null;
169		}
170	}
171	
172	async function insertReceipt(
173		supabase: SupabaseClient,
174		receiptData: Record<string, unknown>
175	): Promise<InsertedReceipt | null> {
176		console.log('Attempting to insert receipt with RPC...');
177		// Use RPC to insert with proper user context
178		const { data, error } = await supabase.rpc('insert_receipt_with_context', {
179			receipt_data: receiptData
180		});
181	
182		if (error) {
183			console.error('RPC insert failed:', JSON.stringify(error, null, 2));
184			console.log('Falling back to direct insert...');
185	
186			// Fallback to direct insert - bypass RLS with service role
187			const { data: directData, error: directError } = await supabase
188				.from('receipts')
189				.insert(receiptData)
190				.select('*')
191				.single();
192	
193			if (directError) {
194				console.error('Direct insert also failed:', JSON.stringify(directError, null, 2));
195				throw directError;
196			}
197			console.log('Direct insert succeeded');
198			return directData;
199		}
200	
201		console.log('RPC insert succeeded');
202		return data;
203	}
