// Email notification sender for the Resend webhook handler.
//
// Extracted from resend/index.ts so it can be unit-tested (index.ts calls
// Deno.serve() at import time and cannot load under vitest). The sender now
// RETURNS a result instead of swallowing failures — callers must surface a
// failed send so notifications don't fail silently.

export type NotificationType = 'error' | 'warning' | 'success';

export interface SendNotificationResult {
	ok: boolean;
	/** HTTP status from Resend, or 0 if the request threw before a response. */
	status: number;
	/** Resend email id on success. */
	id?: string;
	/** Human-readable failure reason on !ok. */
	error?: string;
}

/**
 * Resolve the "from" address for notification emails.
 *
 * MUST be a sender on a domain that is VERIFIED in the Resend account, or every
 * send returns 403 "Request is forbidden". Configure via the RESEND_FROM_EMAIL
 * secret so the verified address can change without a code deploy. The default
 * is intentionally a placeholder — set the env var in Supabase secrets.
 */
export function resolveFromAddress(): string {
	const denoEnv = (globalThis as { Deno?: { env?: { get?(key: string): string | undefined } } })
		.Deno?.env;
	const configured = denoEnv?.get?.('RESEND_FROM_EMAIL');
	return configured && configured.trim().length > 0
		? configured
		: 'Expense Tracker <receipts@yourfinanciallaunchpad.com>';
}

function buildHtml(
	notificationType: NotificationType,
	title: string,
	message: string,
	originalSubject: string,
	sentAt: string,
	emailId?: string
): string {
	const iconMap = { error: '❌', warning: '⚠️', success: '✅' };
	const colorMap = { error: '#dc2626', warning: '#f59e0b', success: '#16a34a' };
	const icon = iconMap[notificationType];
	const color = colorMap[notificationType];

	return `
<!DOCTYPE html>
<html>
<head>
	<style>
		body {
			font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Arial, sans-serif;
			line-height: 1.6;
			color: #333;
		}
		.container {
			max-width: 600px;
			margin: 0 auto;
			padding: 20px;
		}
		.header {
			text-align: center;
			padding: 20px 0;
		}
		.icon {
			font-size: 48px;
			margin-bottom: 10px;
		}
		.notification-box {
			background: #f9fafb;
			border-left: 4px solid ${color};
			padding: 20px;
			margin: 20px 0;
			border-radius: 4px;
		}
		.notification-box h2 {
			margin-top: 0;
			color: ${color};
		}
		.actions {
			background: #ffffff;
			border: 1px solid #e5e7eb;
			border-radius: 8px;
			padding: 20px;
			margin: 20px 0;
		}
		.actions h3 {
			margin-top: 0;
			font-size: 16px;
		}
		.actions ul {
			margin: 10px 0;
			padding-left: 20px;
		}
		.actions li {
			margin: 8px 0;
		}
		.cta-button {
			display: inline-block;
			background: #2563eb;
			color: white !important;
			padding: 12px 24px;
			text-decoration: none;
			border-radius: 6px;
			margin: 15px 0 5px 0;
			font-weight: 500;
		}
		.footer {
			margin-top: 30px;
			padding-top: 20px;
			border-top: 1px solid #e5e7eb;
			color: #6b7280;
			font-size: 13px;
		}
		.footer-info {
			margin: 5px 0;
		}
	</style>
</head>
<body>
	<div class="container">
		<div class="header">
			<div class="icon">${icon}</div>
		</div>

		<div class="notification-box">
			<h2>${title}</h2>
			<p>${message}</p>
		</div>

		${
			notificationType === 'error' || notificationType === 'warning'
				? `
		<div class="actions">
			<h3>What you can do:</h3>
			<ul>
				<li>📸 Forward the email again with a clearer, well-lit photo</li>
				<li>📄 Send the receipt as a PDF attachment instead of an image</li>
				<li>🖼️ Make sure the entire receipt is visible and in focus</li>
				<li>💻 Upload directly through the web app (see button below)</li>
			</ul>
			<a href="https://app.yourfinanciallaunchpad.com/receipts" class="cta-button">
				Upload Receipt Directly
			</a>
		</div>
		`
				: ''
		}

		<div class="footer">
			<div class="footer-info"><strong>Original email:</strong> "${originalSubject}"</div>
			<div class="footer-info"><strong>Sent at:</strong> ${sentAt}</div>
			${emailId ? `<div class="footer-info"><strong>Email ID:</strong> ${emailId}</div>` : ''}
			<div class="footer-info" style="margin-top: 15px;">
				<em>This is an automated notification from your expense tracker.</em>
			</div>
		</div>
	</div>
</body>
</html>
	`;
}

/**
 * Send an email notification to the user about receipt processing status.
 *
 * Returns a {@link SendNotificationResult}. Unlike the previous implementation,
 * it does NOT swallow failures: a non-2xx response or a thrown request produces
 * `{ ok: false, ... }` so the caller can record the failure durably (in-app
 * notice + admin alert). It still never throws — the webhook must keep
 * processing even when notifications can't be delivered.
 */
export async function sendNotificationEmail(
	apiKey: string,
	toEmail: string,
	notificationType: NotificationType,
	title: string,
	message: string,
	originalSubject: string,
	emailId?: string
): Promise<SendNotificationResult> {
	const subjectPrefix = { error: 'Failed', warning: 'Warning', success: 'Success' };
	const subject = `Receipt ${subjectPrefix[notificationType]}: "${originalSubject}"`;
	const from = resolveFromAddress();
	const html = buildHtml(
		notificationType,
		title,
		message,
		originalSubject,
		new Date().toLocaleString(),
		emailId
	);

	try {
		const response = await fetch('https://api.resend.com/emails', {
			method: 'POST',
			headers: {
				Authorization: `Bearer ${apiKey}`,
				'Content-Type': 'application/json'
			},
			body: JSON.stringify({ from, to: [toEmail], subject, html })
		});

		if (!response.ok) {
			const errorText = await response.text();
			console.error('Failed to send notification email:', response.status, errorText);
			return {
				ok: false,
				status: response.status,
				error: `Resend responded ${response.status}: ${errorText}`
			};
		}

		const result = (await response.json().catch(() => ({}))) as { id?: string };
		console.log(`Notification email sent to ${toEmail}:`, result);
		return { ok: true, status: response.status, id: result?.id };
	} catch (err) {
		console.error('Error sending notification email:', err);
		return { ok: false, status: 0, error: err instanceof Error ? err.message : String(err) };
	}
}

