6	 * and, when the receipt itself yielded no date, silently inserted a NULL date
7	 * with no warning to the user (`isSuspiciousDate(null)` is `false`). This module
8	 * hoists that logic into one handler so every path shares identical null-date
9	 * behaviour:
10	 *
11	 *   1. Use the receipt's own date (OCR / text extraction), corrected and
12	 *      suspicious-checked exactly as before.
13	 *   2. If that's null, fall back to the *forwarded email's* original send date —
14	 *      recovered from the quoted `Date:` / `Sent:` header inside the body. For an
15	 *      e-receipt this is effectively the purchase date, and it is run through the
16	 *      same suspicious-window check so a stale forward still gets flagged.
17	 *   3. If neither yields a date, return `dateSource: 'none'` so the caller can
18	 *      warn the user instead of dropping the receipt in silently.
19	 *
20	 * Note the forwarded date is deliberately parsed only from month-name or ISO
21	 * forms — never bare numeric `06/07/2026`, which is DD/MM vs MM/DD ambiguous.
22	 */
23	
24	import { resolveOcrReceiptDate } from './receiptDateCorrection.ts';
25	
26	export type EmailReceiptDateSource = 'receipt' | 'forwarded-email' | 'none';
27	
28	export type EmailReceiptDateResult = {
29		transaction_date: string | null;
30		suspicious_date: boolean;
31		dateSource: EmailReceiptDateSource;
32	};
33	
34	const MONTHS: Record<string, number> = {
35		jan: 1,
36		feb: 2,
37		mar: 3,
38		apr: 4,
39		may: 5,
40		jun: 6,
41		jul: 7,
42		aug: 8,
43		sep: 9,
44		oct: 10,
45		nov: 11,
46		dec: 12
47	};
48	
49	const MONTH_RE = '(jan|feb|mar|apr|may|jun|jul|aug|sep|oct|nov|dec)';
50	
51	/** Build a YYYY-MM-DD string, rejecting impossible calendar dates (e.g. Feb 30). */
52	function buildIso(year: number, month: number, day: number): string | null {
53		if (!Number.isFinite(year) || !Number.isFinite(month) || !Number.isFinite(day)) return null;
54		if (month < 1 || month > 12 || day < 1 || day > 31) return null;
55		// Local-time construction avoids any UTC day-shift; we only read back the parts.
56		const date = new Date(year, month - 1, day);
57		if (date.getFullYear() !== year || date.getMonth() !== month - 1 || date.getDate() !== day) {
58			return null;
59		}
60		const m = String(month).padStart(2, '0');
61		const d = String(day).padStart(2, '0');
62		return `${year}-${m}-${d}`;
63	}
64	
65	/**
66	 * Extract a calendar date from a single mail-header value (the text after
67	 * `Date:` / `Sent:`). Reads the literal day/month/year tokens only — never the
68	 * time or timezone — so the sender's local calendar date is preserved without
69	 * any timezone conversion.
70	 */
71	function parseHeaderDateValue(value: string): string | null {
72		// ISO 8601 first: "2026-07-06".
73		const iso = value.match(/\b(\d{4})-(\d{2})-(\d{2})\b/);
74		if (iso) return buildIso(Number(iso[1]), Number(iso[2]), Number(iso[3]));
75	
76		// "July 6, 2026" / "Jul 6 2026" (month day, year) — Gmail, Apple, Outlook.
77		const mdy = value.match(
78			new RegExp(`\\b${MONTH_RE}[a-z]*\\.?\\s+(\\d{1,2})(?:st|nd|rd|th)?,?\\s+(\\d{4})\\b`, 'i')
79		);
80		if (mdy) return buildIso(Number(mdy[3]), MONTHS[mdy[1].toLowerCase()], Number(mdy[2]));
81	
82		// "6 Jul 2026" (day month year) — RFC 2822 raw Date header.
83		const dmy = value.match(
84			new RegExp(`\\b(\\d{1,2})(?:st|nd|rd|th)?\\s+${MONTH_RE}[a-z]*\\.?,?\\s+(\\d{4})\\b`, 'i')
85		);
86		if (dmy) return buildIso(Number(dmy[3]), MONTHS[dmy[2].toLowerCase()], Number(dmy[1]));
87	
88		return null;
89	}
90	
91	/**
92	 * Recover the original send date of a forwarded email from its body text.
93	 *
94	 * When a receipt email is forwarded, mail clients quote the original headers as
95	 * a `Date:` (Gmail/Apple/RFC) or `Sent:` (Outlook) line. We scan for the first
96	 * such line that parses to a real calendar date and return it as YYYY-MM-DD.
97	 * Returns null when the body has no parseable forwarded-header date (e.g. a
98	 * freshly composed email, or an HTML-only body that hid the headers in markup).
99	 */
100	export function extractForwardedDate(body: string | null | undefined): string | null {
101		if (!body) return null;
102		// Anchor to line start (allowing quote `>` and leading whitespace) so we match
103		// the quoted header block, not a stray "…Date:" inside receipt prose.
104		const lineRe = /^[ \t>]*(?:date|sent):[ \t]*(.+)$/gim;
105		let match: RegExpExecArray | null;
106		while ((match = lineRe.exec(body)) !== null) {
107			const parsed = parseHeaderDateValue(match[1]);
108			if (parsed) return parsed;
109		}
110		return null;
111	}
112	
113	/**
114	 * The single null-date handler shared by every Resend insert path.
115	 *
116	 * `uploadDate` is the reference "now" for the plausibility and suspicious-date
117	 * windows (passed in rather than read from the clock, so it stays pure/testable).
118	 */
119	export function resolveEmailReceiptDate(
120		transactionDate: string | null,
121		rawDateText: string | null | undefined,
122		emailBodyText: string | null | undefined,
123		uploadDate: Date
124	): EmailReceiptDateResult {
125		// 1. The receipt's own date wins whenever we have one.
126		const fromReceipt = resolveOcrReceiptDate(transactionDate, rawDateText, uploadDate);
127		if (fromReceipt.transaction_date) {
128			return { ...fromReceipt, dateSource: 'receipt' };
129		}
130	
131		// 2. Fall back to the forwarded email's date, run through the same checks so a
132		//    stale forward (>42 days) is still flagged suspicious.
133		const forwarded = extractForwardedDate(emailBodyText);
134		if (forwarded) {
135			const fromEmail = resolveOcrReceiptDate(forwarded, null, uploadDate);
136			if (fromEmail.transaction_date) {
137				return { ...fromEmail, dateSource: 'forwarded-email' };
138			}
139		}
140	
141		// 3. No date anywhere — surface it so the caller can warn the user.
142		return { transaction_date: null, suspicious_date: false, dateSource: 'none' };
143	}
