/**
 * Tests for the Resend notification sender.
 *
 * Regression coverage for the "email receipts failing silently" bug:
 *  - A 403 "Request is forbidden" from Resend (unverified `from` domain) must be
 *    SURFACED to the caller, not swallowed. This is the defect that hid the
 *    failure for 30 days.
 *  - The `from` address must come from RESEND_FROM_EMAIL config so it can point
 *    at a verified domain without a code deploy — the hardcoded placeholder was
 *    the root cause of the 403.
 */

import { describe, it, expect, beforeEach, afterEach, vi } from 'vitest';
import { sendNotificationEmail, resolveFromAddress } from './notify.ts';

// The shared module reads Deno.env; under vitest we stand in a minimal shim.
type DenoGlobal = typeof globalThis & { Deno?: { env: { get(key: string): string | undefined } } };
const g = globalThis as DenoGlobal;

function mockDenoEnv(vars: Record<string, string>) {
	g.Deno = { env: { get: (k: string) => vars[k] } };
}

describe('sendNotificationEmail', () => {
	beforeEach(() => {
		delete g.Deno;
		vi.restoreAllMocks();
	});

	afterEach(() => {
		delete g.Deno;
		vi.unstubAllGlobals();
	});

	it('surfaces a 403 "Request is forbidden" instead of swallowing it', async () => {
		const fetchMock = vi
			.fn()
			.mockResolvedValue(
				new Response('{"statusCode":403,"message":"Request is forbidden"}', { status: 403 })
			);
		vi.stubGlobal('fetch', fetchMock);

		const result = await sendNotificationEmail(
			'test-key',
			'doris@yourfinanciallaunchpad.com',
			'success',
			'Receipt Added Successfully',
			'Your receipt from Costco.ca for $621.49 has been added.',
			'Fwd: Your Costco.ca Order Number 1297046014 is Confirmed.',
			'd6bd30d1-111a-4def-885d-d526e926eb02'
		);

		expect(fetchMock).toHaveBeenCalledOnce();
		expect(result.ok).toBe(false);
		expect(result.status).toBe(403);
		expect(result.error).toContain('403');
	});

	it('reports success with the Resend email id on a 200', async () => {
		const fetchMock = vi
			.fn()
			.mockResolvedValue(new Response('{"id":"email-abc"}', { status: 200 }));
		vi.stubGlobal('fetch', fetchMock);

		const result = await sendNotificationEmail(
			'test-key',
			'user@example.com',
			'error',
			'No Receipt Found',
			'nope',
			'subject'
		);

		expect(result.ok).toBe(true);
		expect(result.status).toBe(200);
		expect(result.id).toBe('email-abc');
	});

	it('does not throw when the request itself fails (network error)', async () => {
		const fetchMock = vi.fn().mockRejectedValue(new Error('network down'));
		vi.stubGlobal('fetch', fetchMock);

		const result = await sendNotificationEmail(
			'test-key',
			'user@example.com',
			'warning',
			'title',
			'message',
			'subject'
		);

		expect(result.ok).toBe(false);
		expect(result.status).toBe(0);
		expect(result.error).toContain('network down');
	});

	it('sends from the RESEND_FROM_EMAIL configured address', async () => {
		mockDenoEnv({ RESEND_FROM_EMAIL: 'Expense Tracker <receipts@verified.example.com>' });
		const fetchMock = vi.fn().mockResolvedValue(new Response('{"id":"x"}', { status: 200 }));
		vi.stubGlobal('fetch', fetchMock);

		await sendNotificationEmail('k', 'user@example.com', 'success', 't', 'm', 's');

		const body = JSON.parse((fetchMock.mock.calls[0][1] as RequestInit).body as string);
		expect(body.from).toBe('Expense Tracker <receipts@verified.example.com>');
	});

	it('resolveFromAddress prefers config and never yields an empty domain', () => {
		delete g.Deno;
		// No env configured → default must still be a complete address, never "test@".
		const fallback = resolveFromAddress();
		expect(fallback).toMatch(/@[^>\s]+\.[^>\s]+/);

		mockDenoEnv({ RESEND_FROM_EMAIL: 'A <a@b.com>' });
		expect(resolveFromAddress()).toBe('A <a@b.com>');
	});
});

