// Attachment filtering helpers for Resend webhook email processing
// Specs: #{#eaf1a}, #{#eaf2a}, #{#eaf3a}, #{#eaf5a}

export interface AttachmentMetadata {
	id?: string;
	filename: string;
	content_type: string;
	content_disposition?: string;
	content_id?: string;
}

export interface OcrResultData {
	merchant_name?: string | null;
	total_amount?: number | null;
}

// #{#eaf1a} Supported MIME types for receipt attachments
export const SUPPORTED_RECEIPT_TYPES = new Set<string>([
	'application/pdf',
	'image/jpeg',
	'image/png',
	'image/heic'
]);

// #{#eaf1a} Map file extensions to MIME types for fallback detection
export const EXTENSION_TO_MIME: Record<string, string> = {
	pdf: 'application/pdf',
	jpg: 'image/jpeg',
	jpeg: 'image/jpeg',
	png: 'image/png',
	heic: 'image/heic'
};

/**
 * #{#eaf1a} Check if an attachment has a supported receipt MIME type.
 * Falls back to file extension when content_type is missing or generic.
 */
export function isSupportedReceiptType(contentType: string, filename?: string): boolean {
	const ct = contentType.toLowerCase().trim();

	if (SUPPORTED_RECEIPT_TYPES.has(ct)) {
		return true;
	}

	// Fall back to file extension when content_type is generic or empty
	if (!ct || ct === 'application/octet-stream') {
		if (!filename) return false;
		const ext = filename.split('.').pop()?.toLowerCase();
		if (!ext) return false;
		return ext in EXTENSION_TO_MIME;
	}

	return false;
}

/**
 * #{#eaf2a} Check if an attachment is an inline image (signature, logo, tracking pixel).
 * Inline attachments have content_id set AND content_disposition containing "inline".
 */
export function isInlineAttachment(att: AttachmentMetadata): boolean {
	return !!(att.content_id && att.content_disposition?.toLowerCase().includes('inline'));
}

/**
 * #{#eaf3a} Check if OCR results contain usable data.
 * At least merchant_name or total_amount must be present.
 */
export function hasUsableOcrData(result: OcrResultData): boolean {
	return result.merchant_name != null || result.total_amount != null;
}

/**
 * #{#eaf5a} Check if webhook attachment metadata contains any supported receipt attachments.
 * Used to decide whether to prioritize attachments over body text.
 */
export function hasSupportedAttachments(attachments: AttachmentMetadata[]): boolean {
	return attachments.some(
		(att) => !isInlineAttachment(att) && isSupportedReceiptType(att.content_type, att.filename)
	);
}

