22		// display name can itself contain stray brackets, but the real address is the
23		// final angle-bracket pair (e.g. `"<weird> Name" <a@b.com>`).
24		const angleGroups = candidate.match(/<([^<>]*)>/g);
25		if (angleGroups && angleGroups.length > 0) {
26			const last = angleGroups[angleGroups.length - 1];
27			candidate = last.slice(1, -1).trim();
28		}
29	
