// Parsing helpers for inbound email metadata from the Resend webhook.

/**
 * Extract the bare email address from a mail `from` / sender value.
 *
 * Resend delivers `from` either as a bare address (`a@b.com`) or in RFC 5322
 * display-name form (`Name <a@b.com>`, and often quoted: `"Last, First" <a@b.com>`).
 * `find_user_by_email` does an exact match on the address, so the display name
 * and angle brackets must be stripped — otherwise a legitimately registered user
 * who forwards from a client that includes their display name gets a spurious
 * "User not found".
 *
 * Returns the lowercased address, or null when no usable address is present
 * (empty input, or a value that doesn't look like an email after extraction).
 */
export function parseSenderEmail(from: string | null | undefined): string | null {
	if (!from) return null;

	let candidate = from.trim();

	// Prefer the address inside angle brackets. Use the LAST `<...>` group: a
	// display name can itself contain stray brackets, but the real address is the
	// final angle-bracket pair (e.g. `"<weird> Name" <a@b.com>`).
	const angleGroups = candidate.match(/<([^<>]*)>/g);
	if (angleGroups && angleGroups.length > 0) {
		const last = angleGroups[angleGroups.length - 1];
		candidate = last.slice(1, -1).trim();
	}

	candidate = candidate.toLowerCase();

	// Sanity check: a single `@`, and no internal whitespace, with a dotted
	// domain. Rejects leftover display-name text so the caller can 400 rather
	// than pass garbage to the lookup.
	if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(candidate)) return null;

	return candidate;
}

