9	export function errText(e: unknown): string {
10		if (e instanceof Error) return e.message;
11		if (e && typeof e === 'object' && 'message' in e) {
12			const m = (e as { message: unknown }).message;
13			if (typeof m === 'string') return m;
14		}
15		if (typeof e === 'string') return e;
16		// JSON.stringify(undefined) / a function returns `undefined`, so fall back to
17		// String() to always honour the `: string` return type.
18		return JSON.stringify(e) ?? String(e);
19	}
