/**
 * Best-effort human-readable message from an unknown thrown value.
 *
 * `catch` bindings are `unknown` — the thrown thing can be an `Error`, a
 * Supabase/Postgrest error object (`{ message, code, ... }`), a bare string, or
 * anything else. This collapses all of them to a string suitable for logging and
 * for the `processingErrors` the webhook accumulates.
 */
export function errText(e: unknown): string {
	if (e instanceof Error) return e.message;
	if (e && typeof e === 'object' && 'message' in e) {
		const m = (e as { message: unknown }).message;
		if (typeof m === 'string') return m;
	}
	if (typeof e === 'string') return e;
	// JSON.stringify(undefined) / a function returns `undefined`, so fall back to
	// String() to always honour the `: string` return type.
	return JSON.stringify(e) ?? String(e);
}

