/**
 * Tests for inbound sender-email parsing.
 *
 * Regression coverage for "User not found for sender email": the webhook must
 * look up the user by the bare address, not the raw `from` header. A forwarded
 * receipt whose `from` includes a display name (`Name <addr>`) previously failed
 * the exact-match lookup even for registered users.
 */

import { describe, it, expect } from 'vitest';
import { parseSenderEmail } from './emailParsing.ts';

describe('parseSenderEmail', () => {
	it('returns a bare address unchanged (lowercased)', () => {
		expect(parseSenderEmail('mark@agilepainrelief.com')).toBe('mark@agilepainrelief.com');
	});

	it('extracts the address from display-name form', () => {
		expect(parseSenderEmail('Mark Levison <mark@agilepainrelief.com>')).toBe(
			'mark@agilepainrelief.com'
		);
	});

	it('extracts the address from a quoted display name containing a comma', () => {
		expect(parseSenderEmail('"Levison, Mark" <mark@agilepainrelief.com>')).toBe(
			'mark@agilepainrelief.com'
		);
	});

	it('lowercases the extracted address so it matches the case-insensitive RPC', () => {
		expect(parseSenderEmail('Mark <MARK@Example.COM>')).toBe('mark@example.com');
		expect(parseSenderEmail('DORIS@YOURFINANCIALLAUNCHPAD.COM')).toBe(
			'doris@yourfinanciallaunchpad.com'
		);
	});

	it('trims surrounding whitespace', () => {
		expect(parseSenderEmail('   a@b.com   ')).toBe('a@b.com');
		expect(parseSenderEmail('  Name <a@b.com>  ')).toBe('a@b.com');
	});

	it('uses the final angle-bracket group when the display name has stray brackets', () => {
		expect(parseSenderEmail('"<vip> Name" <real@domain.com>')).toBe('real@domain.com');
	});

	it('returns null for empty / missing input', () => {
		expect(parseSenderEmail(null)).toBeNull();
		expect(parseSenderEmail(undefined)).toBeNull();
		expect(parseSenderEmail('')).toBeNull();
		expect(parseSenderEmail('   ')).toBeNull();
	});

	it('returns null when no usable address can be extracted', () => {
		expect(parseSenderEmail('Just A Name')).toBeNull();
		expect(parseSenderEmail('not-an-email')).toBeNull();
		expect(parseSenderEmail('a@b')).toBeNull(); // no dotted domain
		expect(parseSenderEmail('Name <still not an email>')).toBeNull();
	});
});

