// Deno Deploy / Supabase Edge Function for Resend webhook.
//
// This file is the imperative SHELL: it wires the real runtime collaborators
// (Supabase service client, global fetch, Deno.env, the clock, Mistral OCR,
// the Bank of Canada rate lookup, and svix signature verification) into the
// injectable core `handleResendWebhook` in `handler.ts`. All request→response
// orchestration and branching lives in the core, where it is unit-tested under
// vitest. The only untested lines here are the dependency constructors and the
// one-line `Deno.serve` binding — deliberately trivial, matching the repo's
// "seam-only" testing philosophy.
import { createClient } from 'https://esm.sh/@supabase/supabase-js@2';
import { Webhook } from 'https://esm.sh/svix@1.15.0';
import { handleResendWebhook, type OcrPort } from './handler.ts';
