/** Read an env var via Deno's global without pulling in Deno's type declarations. */
function getEnv(key: string): string | undefined {
	return (
		globalThis as { Deno?: { env?: { get?: (k: string) => string | undefined } } }
	).Deno?.env?.get?.(key);
}

/**
 * Injectable seams for the OCR calls. Optional so production keeps calling these
 * with the Deno runtime / global fetch; the webhook shell passes them explicitly
 * so the network and env access can be redirected.
 */
export interface MistralDeps {
	fetchFn?: typeof fetch;
	env?: (key: string) => string | undefined;
}

/** Parse a possibly-string/number/other value into a finite number, or null. */
function toNum(v: unknown): number | null {
	if (typeof v === 'number') return Number.isFinite(v) ? v : null;
	if (typeof v === 'string') {
		const n = parseFloat(v.replace(/[^0-9.-]/g, ''));
		return Number.isFinite(n) ? n : null;
	}
	return null;
}

/**
 * Extracts receipt fields from an image/PDF URL using Mistral's vision model.
 * Uses the chat completion API with pixtral-12b-2409 (same approach as OcrService.ts).
 * PDFs use document_url, images use image_url.
 * Note: Requires Deno.env to have MISTRAL_API_KEY.
 */
export async function ocrFromUrl(
	fileUrl: string,
	mimeType: string,
	deps: MistralDeps = {}
): Promise<OcrResult> {
	const fetchFn = deps.fetchFn ?? fetch;
	const apiKey = (deps.env ?? getEnv)('MISTRAL_API_KEY');
	if (!apiKey) throw new Error('MISTRAL_API_KEY not set');

	// Determine content type based on MIME type (matches OcrService.ts pattern)
	const isPdf = mimeType.toLowerCase().includes('pdf');
	const contentType = isPdf ? 'document_url' : 'image_url';
	const urlKey = isPdf ? 'document_url' : 'image_url';

	console.log(`OCR processing ${isPdf ? 'PDF' : 'image'}: ${fileUrl.substring(0, 80)}...`);

	const chatRes = await fetchFn('https://api.mistral.ai/v1/chat/completions', {
		method: 'POST',
		headers: {
			Authorization: `Bearer ${apiKey}`,
			'Content-Type': 'application/json'
		},
		body: JSON.stringify({
			model: 'pixtral-12b-2409',
			messages: [
				{
					role: 'user',
					content: [
						{
							type: 'text',
							text: 'Extract fields from the receipt. Respond as JSON with keys: transaction_date (YYYY-MM-DD), raw_date_text (the date exactly as printed on the receipt, verbatim — keep the original separators and digits, do not reinterpret), total_amount (number), tax (number), merchant_name (string), currency (ISO 4217), credit_card_name (string), credit_card_last_4 (string). Default currency to CAD unless the receipt explicitly states a different currency. A bare "$" sign means CAD.'
						},
						{
							type: contentType,
							[urlKey]: fileUrl
						}
					]
				}
			],
			response_format: { type: 'json_object' }
		})
	});

	if (!chatRes.ok) {
		const errorText = await chatRes.text();
		throw new Error(`Mistral vision API failed ${chatRes.status}: ${errorText}`);
	}

	const data = await chatRes.json();
	let content: RawOcrContent = {};
	try {
		const text = data?.choices?.[0]?.message?.content ?? '{}';
		content = typeof text === 'string' ? JSON.parse(text) : text;
	} catch {
		/* keep content as {} when the model returns non-JSON */
	}

	return {
		transaction_date: content?.transaction_date ?? null,
		raw_date_text: content?.raw_date_text ?? null,
		total_amount: toNum(content?.total_amount),
		tax: toNum(content?.tax),
		merchant_name: content?.merchant_name ?? null,
		currency: content?.currency ?? null,
		credit_card_name: content?.credit_card_name ?? null,
		credit_card_last_4: content?.credit_card_last_4 ?? null
	};
}

/**
 * Processes email text with Mistral to extract receipt information.
 * Returns receipt data if found, or null if no receipt detected.
 */
export async function processEmailText(
	emailText: string,
	deps: MistralDeps = {}
): Promise<OcrResult | null> {
	const fetchFn = deps.fetchFn ?? fetch;
	const apiKey = (deps.env ?? getEnv)('MISTRAL_API_KEY');
	if (!apiKey) throw new Error('MISTRAL_API_KEY not set');

	console.log('=== Sending text to Mistral (pixtral-12b) ===');
	console.log('Text length:', emailText.length);
	console.log('Text preview (first 500 chars):', emailText.substring(0, 500));
	console.log('============================================');

	const res = await fetch('https://api.mistral.ai/v1/chat/completions', {
		method: 'POST',
		headers: {
			Authorization: `Bearer ${apiKey}`,
			'Content-Type': 'application/json'
		},
		body: JSON.stringify({
			model: 'pixtral-12b-2409',
			messages: [
				{
					role: 'system',
					content:
						'You are a receipt analyzer. Analyze the provided text and determine if it contains receipt information. If it does, extract the receipt fields. If it does not contain receipt information, respond with {"is_receipt": false}.'
				},
				{
					role: 'user',
					content: `Analyze this email text and extract receipt information if present. Return JSON with: is_receipt (boolean), transaction_date (YYYY-MM-DD), raw_date_text (the date exactly as printed in the email, verbatim — keep original separators and digits, do not reinterpret), total_amount, tax, merchant_name, currency (ISO 4217, default CAD unless explicitly stated otherwise — a bare "$" means CAD), credit_card_name, credit_card_last_4.\n\nEmail text:\n${emailText}`
				}
			],
			response_format: { type: 'json_object' }
		})
	});

	if (!res.ok) {
		console.error('Mistral API error:', res.status, await res.text());
		throw new Error(`Mistral API failed ${res.status}`);
	}

	const data = await res.json();
	console.log('=== Mistral Response ===');
	console.log(JSON.stringify(data, null, 2));
	console.log('========================');

	let content: RawOcrContent = {};
	try {
		const text = data?.choices?.[0]?.message?.content ?? '{}';
		content = typeof text === 'string' ? JSON.parse(text) : text;
	} catch (e) {
		console.error('Failed to parse Mistral response:', e);
		return null;
	}

	// Check if Mistral detected a receipt
	if (content.is_receipt === false) {
		console.log('Mistral determined this is not a receipt');
		return null;
	}

	return {
		transaction_date: content?.transaction_date ?? null,
		raw_date_text: content?.raw_date_text ?? null,
		total_amount: toNum(content?.total_amount),
		tax: toNum(content?.tax),
		merchant_name: content?.merchant_name ?? null,
		currency: content?.currency ?? null,
		credit_card_name: content?.credit_card_name ?? null,
		credit_card_last_4: content?.credit_card_last_4 ?? null
	};
}

/**
 * Converts text to an SVG image by rendering it.
 * Returns the SVG content as a Uint8Array.
 */
export async function textToImage(text: string): Promise<Uint8Array> {
	// Create an SVG representation of the text

	const maxWidth = 800;
	const fontSize = 14;
	const lineHeight = 20;
	const padding = 20;

	// Split text into lines that fit within maxWidth
	const lines = text.split('\n');
	const height = lines.length * lineHeight + padding * 2;

	// Create SVG
	const svgContent = `<?xml version="1.0" encoding="UTF-8"?>
<svg width="${maxWidth}" height="${height}" xmlns="http://www.w3.org/2000/svg">
  <rect width="100%" height="100%" fill="white"/>
  <text x="${padding}" y="${padding + fontSize}" font-family="monospace" font-size="${fontSize}" fill="black">
    ${lines.map((line, i) => `<tspan x="${padding}" dy="${i === 0 ? 0 : lineHeight}">${escapeXml(line)}</tspan>`).join('\n    ')}
  </text>
</svg>`;

	// Encode the SVG as UTF-8 bytes
	const encoder = new TextEncoder();
	return encoder.encode(svgContent);
}

function escapeXml(unsafe: string): string {
	return unsafe
		.replace(/&/g, '&amp;')
		.replace(/</g, '&lt;')
		.replace(/>/g, '&gt;')
		.replace(/"/g, '&quot;')
		.replace(/'/g, '&apos;');
}

