/**
 * Shared Exchange Rate Utility
 *
 * This utility is used by both:
 * - Frontend (src/lib/services/ExchangeRateService.ts)
 * - Backend Edge Functions (supabase/functions/resend/index.ts)
 *
 * Implements #{#fcr2a} - Fetches daily exchange rates from the Bank of Canada
 * Valet API. Free, no API key required.
 */

const SUPPORTED_CURRENCIES: Record<string, string> = {
	EUR: 'FXEURCAD',
	USD: 'FXUSDCAD',
	GBP: 'FXGBPCAD'
};

const BOC_BASE_URL = 'https://www.bankofcanada.ca/valet/observations';

/**
 * Fetch the Bank of Canada daily exchange rate for a currency on a given date.
 * Returns the rate as a number (e.g., 1.6058 for EUR→CAD), or null if unavailable.
 *
 * If the exact date has no rate (weekend/holiday), returns the most recent
 * available rate within 5 business days.
 */
export async function fetchExchangeRate(currency: string, date: string): Promise<number | null> {
	const seriesCode = SUPPORTED_CURRENCIES[currency];
	if (!seriesCode) return null;

	try {
		const endDate = date;
		const startDate = subtractDays(date, 7);

		const url = `${BOC_BASE_URL}/${seriesCode}/json?start_date=${startDate}&end_date=${endDate}`;
		const response = await fetch(url);

		if (!response.ok) return null;

		const data = await response.json();
		const observations = data.observations;

		if (!observations || observations.length === 0) return null;

		const latest = observations[observations.length - 1];
		const rateStr = latest[seriesCode]?.v;

		if (!rateStr) return null;

		return parseFloat(rateStr);
	} catch {
		return null;
	}
}

function subtractDays(dateStr: string, days: number): string {
	const [year, month, day] = dateStr.split('-').map(Number);
	const date = new Date(year, month - 1, day);
	date.setDate(date.getDate() - days);
	const y = date.getFullYear();
	const m = String(date.getMonth() + 1).padStart(2, '0');
	const d = String(date.getDate()).padStart(2, '0');
	return `${y}-${m}-${d}`;
}

