/**
 * Branch-matrix coverage for the Resend webhook handler.
 *
 * These exercise `handleResendWebhook` — the injectable core extracted from the
 * old top-level `Deno.serve` body — with a fabricated `Request` and fully faked
 * `deps` (in-memory Supabase double, a URL-routed `fetchFn`, stub `ocr` /
 * `exchangeRate` / `verifySignature`). No network, no live Supabase, no Deno
 * runtime. Each `it` maps to a row in the PRD test plan (§5).
 *
 * See prd-resend-handler-testability.md.
 */

import { describe, it, expect, vi } from 'vitest';
import type { SupabaseClient } from 'https://esm.sh/@supabase/supabase-js@2';
import { handleResendWebhook, type OcrPort, type WebhookDeps } from './handler.ts';
import type { OcrResult } from '../_shared/mistral.ts';

// A fixed "now" so suspicious-date checks and timestamps are deterministic.
const NOW = new Date('2026-07-06T12:00:00Z');

const FULL_ENV: Record<string, string> = {
	SUPABASE_URL: 'https://project.supabase.co',
	SUPABASE_SERVICE_ROLE_KEY: 'service-role-key',
	RESEND_API_KEY: 'resend-api-key',
	RESEND_WEBHOOK_SECRET: 'whsec_test'
};

function usableOcr(over: Partial<OcrResult> = {}): OcrResult {
	return {
		transaction_date: '2026-07-01',
		raw_date_text: null,
		total_amount: 42.5,
		tax: 2,
		merchant_name: 'Costco',
		currency: 'CAD',
		credit_card_name: null,
		credit_card_last_4: null,
		...over
	};
}

const UNUSABLE_OCR: OcrResult = usableOcr({ merchant_name: null, total_amount: null });

function ocrStub(over: Partial<OcrPort> = {}): OcrPort {
	return {
		processEmailText: over.processEmailText ?? vi.fn(async () => usableOcr()),
		textToImage: over.textToImage ?? vi.fn(async () => new Uint8Array([1, 2, 3])),
		ocrFromUrl: over.ocrFromUrl ?? vi.fn(async () => usableOcr())
	};
}

interface EventOverrides {
	type?: string;
	from?: string;
	subject?: string;
	attachments?: Array<{
		id: string;
		filename: string;
		content_type: string;
		content_disposition?: string;
		content_id?: string;
	}>;
}

function makeEvent(over: EventOverrides = {}): Record<string, unknown> {
	return {
		type: 'type' in over ? over.type : 'email.received',
		created_at: '2026-07-06T00:00:00Z',
		data: {
			email_id: 'em-1',
			from: over.from ?? 'user@example.com',
			to: ['receipts@yourfinanciallaunchpad.com'],
			subject: over.subject ?? 'Fwd: Your receipt',
			created_at: '2026-07-06T00:00:00Z',
			message_id: 'mid-1',
			bcc: [],
			cc: [],
			attachments: over.attachments ?? []
		}
	};
}

function makeRequest(body: unknown, method = 'POST'): Request {
	const init: RequestInit = {
		method,
		headers: { 'Content-Type': 'application/json' }
	};
	// GET/HEAD requests cannot carry a body per the fetch spec.
	if (method !== 'GET' && method !== 'HEAD') {
		init.body = typeof body === 'string' ? body : JSON.stringify(body);
	}
	return new Request('https://fn.example/resend', init);
}

interface SetupOptions {
	env?: Record<string, string>;
	verifySignature?: boolean;
	userId?: string | null;
	userErr?: { message: string } | null;
	ocr?: OcrPort;
	exchangeRate?: WebhookDeps['exchangeRate'];
	notifyStatus?: number;
	routes?: {
		emailContent?: () => Response;
		attachments?: () => Response;
		download?: (url: string) => Response;
	};
}

interface Harness {
	deps: WebhookDeps;
	receiptInserts: Array<Record<string, unknown>>;
	failures: Array<Record<string, unknown>>;
	notifications: Array<{ subject: string; html: string; to: string[]; from: string }>;
	fetchFn: ReturnType<typeof vi.fn>;
	exchangeRate: WebhookDeps['exchangeRate'];
	ocr: OcrPort;
}

function setup(o: SetupOptions = {}): Harness {
	const receiptInserts: Array<Record<string, unknown>> = [];
	const failures: Array<Record<string, unknown>> = [];
	const notifications: Harness['notifications'] = [];

	const supabase = {
		rpc: vi.fn(async (fn: string, params: { receipt_data?: Record<string, unknown> }) => {
			if (fn === 'find_user_by_email') {
				return { data: 'userId' in o ? o.userId : 'user-123', error: o.userErr ?? null };
			}
			if (fn === 'insert_receipt_with_context') {
				const rd = params.receipt_data as Record<string, unknown>;
				receiptInserts.push(rd);
				return {
					data: { id: 'r1', merchant_name: rd.merchant_name, total_amount: rd.total_amount },
					error: null
				};
			}
			return { data: null, error: null };
		}),
		from: vi.fn((table: string) => ({
			insert: (row: Record<string, unknown>) => {
				if (table === 'email_send_failures') failures.push(row);
				const result = { data: null, error: null };
				return {
					select: () => ({ single: async () => ({ data: { id: 'r1', ...row }, error: null }) }),
					// Thenable so a bare `await from().insert()` resolves to `{ error }`.
					then: (resolve: (v: typeof result) => unknown) => resolve(result)
				};
			}
		})),
		storage: {
			from: () => ({
				upload: vi.fn(async () => ({ error: null })),
				createSignedUrl: vi.fn(async () => ({
					data: { signedUrl: 'https://signed.example/receipt.jpg' },
					error: null
				}))
			})
		}
	};

	const fetchFn = vi.fn(async (url: string | URL | Request, init?: RequestInit) => {
		const u = String(url);
		if (u === 'https://api.resend.com/emails') {
			if (init?.body) notifications.push(JSON.parse(init.body as string));
			return new Response('{"id":"notif-1"}', { status: o.notifyStatus ?? 200 });
		}
		if (u.endsWith('/attachments')) {
			return o.routes?.attachments
				? o.routes.attachments()
